import { gsap } from 'gsap';
import { vec3, uv, mix, smoothstep, time, uniform, color } from 'three/tsl';
import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();
  group.userData.handlers = {};

  const timelines = [];
  const cleanupCallbacks = [];

  // ============================================================================
  // 1. BACKDROP PLANE: 7 x 5.5 units at z=-1.5 with vertical gradient
  // ============================================================================
  const backdropGeometry = new THREE.PlaneGeometry(7, 5.5);

  // Create a simple gradient texture with minimal grain
  const backdropCanvas = document.createElement('canvas');
  backdropCanvas.width = 512;
  backdropCanvas.height = 512;

  const backdropCtx = backdropCanvas.getContext('2d');
  if (backdropCtx) {
    // Vertical gradient: #0b0b10 (top) to #13131a (bottom)
    const gradient = backdropCtx.createLinearGradient(0, 0, 0, backdropCanvas.height);
    gradient.addColorStop(0, '#0b0b10');
    gradient.addColorStop(1, '#13131a');

    backdropCtx.fillStyle = gradient;
    backdropCtx.fillRect(0, 0, backdropCanvas.width, backdropCanvas.height);

    // Add subtle 1.5% mono grain
    const imageData = backdropCtx.getImageData(0, 0, backdropCanvas.width, backdropCanvas.height);
    const data = imageData.data;
    const grainAmount = 0.015;
    for (let i = 0; i < data.length; i += 4) {
      const noise = (Math.random() - 0.5) * 2 * grainAmount * 255;
      data[i] = Math.max(0, Math.min(255, data[i] + noise));
      data[i + 1] = Math.max(0, Math.min(255, data[i + 1] + noise));
      data[i + 2] = Math.max(0, Math.min(255, data[i + 2] + noise));
    }
    backdropCtx.putImageData(imageData, 0, 0);
  }

  const backdropTexture = new THREE.CanvasTexture(backdropCanvas);
  backdropTexture.magFilter = THREE.LinearFilter;
  backdropTexture.minFilter = THREE.LinearFilter;

  const backdropMaterial = new MeshBasicNodeMaterial({
    map: backdropTexture,
    toneMapped: false,
  });

  const backdrop = new THREE.Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.z = -1.5;
  backdrop.renderOrder = 0;
  group.add(backdrop);

  cleanupCallbacks.push(() => {
    if (backdropTexture) backdropTexture.dispose();
  });

  // ============================================================================
  // 2. CAPTION KICKER: "NOVA ATELIER / CALIBRE PROGRAM" at y=1.15
  // ============================================================================
  const captionText = ctx.fontAtlas.createText('NOVA ATELIER / CALIBRE PROGRAM', {
    fontSize: 10,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 1.2,
  });
  captionText.position.set(0, 1.15, 0.1);
  captionText.renderOrder = 10;
  group.add(captionText);

  // ============================================================================
  // 3. HERO HEADLINE: "TIME, MACHINED." — Kinetic glyph-by-glyph entrance
  // ============================================================================
  const heroText = 'TIME, MACHINED.';
  const heroFontSize = 20; // Scaled down to fit scene
  const heroEmHeight = 0.62; // scene units per em

  // Split into words for depth parallax: "TIME," at z=0.12, "MACHINED." at z=-0.12
  const words = [
    { text: 'TIME,', z: 0.12 },
    { text: 'MACHINED.', z: -0.12 },
  ];

  const heroGroup = new THREE.Group();
  heroGroup.position.y = 0.4;
  group.add(heroGroup);

  const allGlyphMeshes = [];
  let glyphIndex = 0;
  let maxGlyphIndex = 0;

  words.forEach((wordData) => {
    const wordMesh = ctx.fontAtlas.createText(wordData.text, {
      fontSize: heroFontSize,
      color: '#e8ecf2',
      align: 'center',
    });
    wordMesh.position.z = wordData.z;
    wordMesh.renderOrder = 20 + Math.floor(wordData.z * 100);
    heroGroup.add(wordMesh);

    // Collect all glyph meshes for staggered animation
    const collectGlyphs = (node) => {
      if (node.isMesh && node !== wordMesh) {
        allGlyphMeshes.push(node);
        maxGlyphIndex = glyphIndex;
        glyphIndex++;
      }
      if (node.children && node.children.length > 0) {
        node.children.forEach(collectGlyphs);
      }
    };

    collectGlyphs(wordMesh);
  });

  // If no children found, treat word meshes as glyphs
  if (allGlyphMeshes.length === 0) {
    words.forEach((wordData) => {
      const mesh = heroGroup.children.find(c => c !== heroGroup && c.isMesh === false);
      if (mesh) {
        allGlyphMeshes.push(mesh);
        maxGlyphIndex++;
      }
    });
  }

  // ============================================================================
  // 4. ACCENT UNDERLINE: 2.6 x 0.045-unit plane, #ff2a38 emissive
  // ============================================================================
  const underlineGeometry = new THREE.PlaneGeometry(2.6, 0.045);
  const underlineMaterial = new MeshBasicNodeMaterial({
    color: '#ff2a38',
    emissive: '#ff2a38',
    emissiveIntensity: 1.2,
    toneMapped: false,
  });

  const underline = new THREE.Mesh(underlineGeometry, underlineMaterial);
  underline.position.set(0, -0.05, 0.15);
  underline.scale.x = 0; // Start at scaleX 0
  underline.renderOrder = 25;
  heroGroup.add(underline);

  // ============================================================================
  // 5. SUBHEAD: "Every calibre begins as a solid billet." at y=-0.65
  // ============================================================================
  const subheadText = ctx.fontAtlas.createText('Every calibre begins as a solid billet.', {
    fontSize: 10,
    color: '#e8ecf2',
    align: 'center',
    maxWidthPx: 400,
    letterSpacingPx: 0.2,
  });
  subheadText.position.set(0, -0.65, 0.1);
  subheadText.renderOrder = 15;
  // Initially hidden for fade-up
  subheadText.traverse((child) => {
    if (child.material) {
      child.material.opacity = 0;
      child.material.transparent = true;
    }
  });
  group.add(subheadText);

  // ============================================================================
  // 6. KINETIC ANIMATION: Per-glyph y entrance + stagger + settle
  // ============================================================================

  const staggerMs = 60;
  const glyphDuration = 0.7; // seconds
  const glyphEasing = 'power2.out';

  const glyphAnimations = [];

  allGlyphMeshes.forEach((mesh, idx) => {
    const delay = (idx * staggerMs) / 1000;

    const tl = gsap.timeline({ paused: true });
    tl.fromTo(
      mesh.position,
      { y: mesh.position.y + 0.35 },
      {
        y: mesh.position.y,
        duration: glyphDuration,
        ease: glyphEasing,
      },
      0
    );

    if (mesh.material && mesh.material.transparent) {
      tl.fromTo(
        mesh.material,
        { opacity: 0 },
        {
          opacity: 1,
          duration: glyphDuration,
          ease: glyphEasing,
        },
        0
      );
    }

    glyphAnimations.push({ timeline: tl, delay });
    timelines.push(tl);
  });

  // ============================================================================
  // 7. WEIGHTED SETTLE: Triggered after final glyph lands
  // ============================================================================
  const settleDuration = 0.9;

  const settleTl = gsap.timeline({ paused: true });
  settleTl.fromTo(
    heroGroup.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: settleDuration,
      ease: 'power4.out',
    },
    0
  );

  timelines.push(settleTl);

  // ============================================================================
  // 8. ACCENT UNDERLINE SCALE: Scale x 0 to 1 over 500ms
  // ============================================================================
  const underlineTl = gsap.timeline({ paused: true });

  underlineTl.fromTo(
    underline.scale,
    { x: 0 },
    {
      x: 1,
      duration: 0.5,
      ease: 'power2.inOut',
    },
    0
  );

  timelines.push(underlineTl);

  // ============================================================================
  // 9. SUBHEAD FADE-UP
  // ============================================================================
  const subheadTl = gsap.timeline({ paused: true });
  const subheadInitialY = subheadText.position.y;

  subheadTl.fromTo(
    subheadText.position,
    { y: subheadInitialY + 0.2 },
    {
      y: subheadInitialY,
      duration: 0.5,
      ease: 'power2.out',
    },
    0
  );

  subheadText.traverse((child) => {
    if (child.material && child.material.transparent) {
      subheadTl.fromTo(
        child.material,
        { opacity: 0 },
        {
          opacity: 1,
          duration: 0.5,
          ease: 'power2.out',
        },
        0
      );
    }
  });

  timelines.push(subheadTl);

  // ============================================================================
  // 10. TIMELINE SEQUENCING
  // ============================================================================

  const finalGlyphTime = maxGlyphIndex * (staggerMs / 1000) + glyphDuration;
  const underlineStartTime = finalGlyphTime + 0.12;

  glyphAnimations.forEach(({ timeline, delay }) => {
    timeline.play(delay);
  });

  settleTl.play(finalGlyphTime);
  underlineTl.play(underlineStartTime);
  subheadTl.play(finalGlyphTime + 0.05);

  // ============================================================================
  // 11. APPLY CINEMATIC PRIMITIVES
  // ============================================================================
  if (config.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((primitive) => {
      if (primitive.name && ctx.primitives[primitive.name]) {
        const result = ctx.primitives[primitive.name](group, primitive.params || {});
        if (result && result.cleanup) {
          cleanupCallbacks.push(result.cleanup);
        }
        if (result && result.timeline) {
          timelines.push(result.timeline);
        }
      }
    });
  }

  // ============================================================================
  // 12. CLEANUP
  // ============================================================================
  group.userData.cleanup = () => {
    timelines.forEach((tl) => {
      if (tl && typeof tl.kill === 'function') {
        tl.kill();
      }
    });
    cleanupCallbacks.forEach((cb) => {
      if (typeof cb === 'function') {
        cb();
      }
    });

    group.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach((m) => m.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
  };

  return group;
}
